// Medical Law & Ethics Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test
// plan, slightly harder than the sample items: applying legal doctrines and ethical principles to cases.
import {q, mix} from './q.js';
const TAM='Tamparo, Medical Law, Ethics, & Bioethics for the Health Professions', FREM='Fremgen, Healthcare Law and Ethics', RIT='Ritter & Graham, Medical Law & Professional Ethics';
const BASIC='The Basics: Medical Law, Ethics and Bioethics', LEGAL='The Legal Environment', HCE='The Health Care Environment', BIO='Bioethical Issues';

export default {
 id:'medical-law-ethics-1',
 event:'Medical Law & Ethics',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Tamparo’s Medical Law, Ethics, & Bioethics, Fremgen’s Healthcare Law and Ethics, and Ritter & Graham’s Medical Law & Professional Ethics',
 plan:[{area:BASIC,weight:5},{area:LEGAL,weight:35},{area:HCE,weight:35},{area:BIO,weight:25}],
 questions:mix([
  q(BASIC,'Which statement best distinguishes law from ethics?','Laws are enforced by government; ethics are standards of conduct',['Ethics are enforced by courts; laws are personal beliefs','Laws and ethics always require the same behavior','Ethics apply only to physicians, and laws to all workers'],'B','Laws are rules enforced by government with penalties. Ethics are moral standards of conduct, often set by professions; an act can be legal but unethical.',FREM),
  q(BASIC,'Which ethical principle means “do good” for the patient?','Beneficence',['Nonmaleficence','Autonomy','Justice'],'A','Beneficence is acting for the patient’s benefit. Nonmaleficence means “do no harm,” autonomy is respect for the patient’s choices, and justice is fair distribution of care.',TAM),
  q(BASIC,'What does the field of bioethics address?','Moral questions raised by medical advances',['Laws governing hospital business practices','Rules for billing insurance companies','Standards for laboratory equipment safety'],'D','Bioethics deals with moral questions arising from medical and biological research and technology, such as genetic testing, organ transplants and end-of-life care.',TAM),
  q(LEGAL,'Who is responsible for obtaining a patient’s informed consent for surgery?','The physician performing the procedure',['The nurse who prepares the patient','The hospital’s admitting clerk','The patient’s closest family member'],'C','The provider performing the procedure must explain its nature, risks, benefits and alternatives. A nurse may witness the patient’s signature but cannot obtain informed consent.',FREM),
  q(LEGAL,'A 17-year-old who is married and lives independently seeks treatment. Why can she consent to her own care?','She is an emancipated minor',['She is under the age of majority','She has implied consent','Her parents gave verbal consent'],'A','Emancipated minors, such as those who are married, in the military or self-supporting, can legally consent to their own medical care.',TAM),
  q(LEGAL,'In most states, which care can a minor consent to without a parent?','STI testing and treatment',['Elective cosmetic surgery','Routine orthopedic surgery','Any procedure the minor requests'],'B','State laws allow minors to consent to certain sensitive services, such as STI testing and treatment, so they are not discouraged from seeking care.',TAM),
  q(LEGAL,'A patient sues a physician for malpractice. Under which branch of law does this case fall?','Civil law',['Criminal law','Administrative law','Constitutional law'],'D','Malpractice is a tort, a civil wrong, and is resolved in civil court with damages paid to the plaintiff. Criminal law involves offenses against the public, prosecuted by the government.',FREM),
  q(LEGAL,'What is a statute of limitations?','The time limit for filing a lawsuit',['The maximum amount of damages allowed','The number of witnesses required in court','The rule that a physician must have a license'],'C','A statute of limitations sets how long a plaintiff has to file a lawsuit. For malpractice, the time often begins when the injury is discovered.',FREM),
  q(LEGAL,'A medical office receives a subpoena duces tecum. What does it require?','Producing specified records',['A physician to appear and testify','The office to pay a fine','The patient to appear in court'],'A','Duces tecum means “bring with you.” This subpoena orders records or documents to be brought to court or a deposition. A regular subpoena orders a person to appear and testify.',FREM),
  q(LEGAL,'What is a deposition?','Sworn testimony taken out of court',['A written ruling by a judge','A formal request to dismiss a lawsuit','A payment made to settle a case'],'B','During discovery, witnesses answer attorneys’ questions under oath, and a court reporter records the testimony for later use at trial.',FREM),
  q(LEGAL,'A medical assistant makes an error while doing her job, and the patient sues the clinic. Which doctrine makes the employer liable?','Respondeat superior',['Res ipsa loquitur','Res judicata','Stare decisis'],'D','Respondeat superior, “let the master answer,” holds employers responsible for employees’ acts within the scope of employment. Employees can still be held personally liable.',TAM),
  q(LEGAL,'After surgery, an X-ray shows a sponge left in the patient’s abdomen. Which doctrine applies?','Res ipsa loquitur',['Respondeat superior','Assumption of risk','Contributory negligence'],'C','“The thing speaks for itself.” The injury would not occur without negligence and was under the defendant’s control, so the burden shifts to the defendant to prove they were not negligent.',FREM),
  q(LEGAL,'A healthcare worker suspects a child is being abused. What is required?','Report the suspicion to authorities',['Confirm the abuse before reporting','Ask the parents for permission to report','Report only if the child asks for help'],'A','Healthcare workers are mandated reporters and must report reasonable suspicion of child abuse. Reporters acting in good faith are protected from liability.',RIT),
  q(LEGAL,'What is the main purpose of Good Samaritan laws?','To protect rescuers acting in good faith',['To require all citizens to help in emergencies','To pay rescuers for emergency care','To protect providers working in hospitals'],'B','Good Samaritan laws protect rescuers who give reasonable emergency care without expecting payment. They do not cover gross negligence or care given as part of a job.',FREM),
  q(LEGAL,'How does licensure differ from certification?','Licensure is required by state law to practice',['Licensure is voluntary and issued by associations','Certification is required by federal law','Certification allows practice in any state'],'A','A license is a mandatory credential granted by the state that allows a person to practice. Certification is usually voluntary and granted by a professional organization.',TAM),
  q(LEGAL,'What do state medical practice acts do?','Define medical practice and licensing rules',['Set prices for medical services','Regulate health insurance companies','Approve new prescription drugs for sale'],'D','Each state’s medical practice act defines medical practice, sets requirements for licensure and describes grounds for revoking or suspending a license.',FREM),
  q(LEGAL,'A patient calls to make an appointment, and the physician agrees to see them. What kind of contract has been formed?','An implied contract',['An expressed written contract','A void contract','A third-party contract'],'C','Most physician-patient contracts are implied by conduct. An expressed contract is stated clearly in words, either spoken or written.',TAM),
  q(LEGAL,'A physician wants to stop treating a patient. To avoid abandonment, what should the physician do?','Give written notice with time to find care',['Stop seeing the patient without notice','Tell the receptionist to cancel future visits','Refer the patient’s records to the insurer'],'B','Withdrawing from a case requires formal written notice, usually by certified mail, with time for the patient to find a new provider and an offer to transfer records.',FREM),
  q(LEGAL,'A worker angrily threatens a patient with an injection, making the patient fear being touched. No contact occurs. Which tort is this?','Assault',['Battery','Defamation','False imprisonment'],'D','Assault is an act that causes a reasonable fear of harmful contact. Battery is the actual unwanted touching.',FREM),
  q(LEGAL,'Under the Controlled Substances Act, which federal agency registers providers who prescribe controlled drugs?','The DEA',['The FDA','The CDC','The FTC'],'C','The Drug Enforcement Administration enforces the Controlled Substances Act and registers prescribers and pharmacies that handle controlled drugs.',FREM),
  q(HCE,'Which four elements must a plaintiff prove to win a negligence case (the four Ds)?','Duty, dereliction, direct cause and damages',['Diagnosis, documentation, delay and death','Duty, dishonesty, disability and damages','Dereliction, deception, delay and debt'],'A','The plaintiff must prove the provider owed a duty, breached it (dereliction), that the breach directly caused the injury, and that damages resulted.',TAM),
  q(HCE,'A nurse performs an ordered procedure but does it incorrectly, injuring the patient. What type of negligence is this?','Misfeasance',['Malfeasance','Nonfeasance','Feasance'],'B','Misfeasance is doing a lawful act improperly. Malfeasance is doing an unlawful or wrongful act, and nonfeasance is failing to act when there is a duty to act.',TAM),
  q(HCE,'Who owns the physical medical record?','The provider or facility',['The patient','The patient’s insurance company','The state health department'],'D','The physical record belongs to the provider or facility. The patient owns the information in it and has the right to see and get copies of it.',FREM),
  q(HCE,'An error is found in a paper medical record. What is the correct way to fix it?','Draw one line through it; initial and date it',['Use correction fluid and write over it','Remove the page and rewrite it neatly','Black out the error so it cannot be read'],'C','The original entry must remain readable so the record cannot be accused of being altered. Erasing or obliterating entries can suggest a cover-up.',FREM),
  q(HCE,'Under the HIPAA Privacy Rule, the “minimum necessary” standard means:','Share only the information needed for the task',['Patients receive the minimum care required by law','Records are kept for the shortest legal time','Only physicians may view a patient’s record'],'A','Workers should use or disclose only the protected health information needed for a given purpose. It does not apply to disclosures for treatment.',FREM),
  q(HCE,'Which disclosure of patient information is allowed without the patient’s authorization?','Reporting a communicable disease to public health',['Telling the patient’s employer about a diagnosis','Sharing results with the patient’s neighbor','Posting the patient’s photo on social media'],'B','HIPAA allows disclosures required by law, such as reporting certain diseases, abuse, births and deaths, without patient authorization.',FREM),
  q(HCE,'Which law strengthened HIPAA enforcement and requires notification when unsecured health information is breached?','The HITECH Act',['The Patient Self-Determination Act','The Affordable Care Act','The Americans with Disabilities Act'],'D','The Health Information Technology for Economic and Clinical Health Act of 2009 promoted electronic records, increased penalties and created breach notification rules.',FREM),
  q(HCE,'Which law prohibits employment discrimination based on race, color, religion, sex or national origin?','Title VII of the Civil Rights Act',['The Fair Labor Standards Act','The Family and Medical Leave Act','The Occupational Safety and Health Act'],'C','Title VII of the Civil Rights Act of 1964 bans employment discrimination on these grounds and applies to employers with 15 or more employees.',RIT),
  q(HCE,'Under the Americans with Disabilities Act, what must employers provide to qualified workers with disabilities?','Reasonable accommodations',['A higher salary','Guaranteed promotions','Unlimited paid leave'],'A','Employers must make reasonable accommodations, such as modified equipment or schedules, unless doing so would cause undue hardship.',RIT),
  q(HCE,'The Family and Medical Leave Act allows eligible employees up to how much job-protected leave per year?','12 weeks of unpaid leave',['6 weeks of paid leave','12 weeks of paid leave','26 weeks of paid leave'],'B','FMLA provides up to 12 weeks of unpaid, job-protected leave for events such as the birth of a child or a serious health condition. Up to 26 weeks is allowed for caring for an injured service member.',RIT),
  q(HCE,'Under OSHA’s Bloodborne Pathogens Standard, what must employers offer workers with occupational exposure risk?','The hepatitis B vaccine at no cost',['A yearly bonus for hazardous work','Free health insurance for family members','Annual HIV testing at the worker’s expense'],'D','Employers must provide the hepatitis B vaccine free of charge, along with PPE, training and an exposure control plan.',RIT),
  q(HCE,'A supervisor tells an employee she will be promoted only if she goes on a date with him. What is this?','Quid pro quo sexual harassment',['Hostile work environment harassment','Constructive discharge','Retaliation'],'C','Quid pro quo means “this for that”: job benefits are tied to sexual favors. A hostile work environment involves unwelcome conduct that makes the workplace intimidating.',RIT),
  q(HCE,'A patient with limited English must decide on a treatment. What is the best way to ensure informed consent?','Use a qualified medical interpreter',['Ask the patient’s child to translate','Use gestures and simple drawings','Have the patient sign an English form'],'A','A qualified interpreter ensures accurate communication of risks and options. Using family members, especially children, risks errors and breaches of privacy.',TAM),
  q(HCE,'What does the Patient Self-Determination Act require of facilities that receive Medicare and Medicaid funds?','Informing patients about advance directives',['Providing free care to all patients','Assigning every patient a guardian','Requiring every patient to sign a DNR order'],'B','Since 1991, hospitals and other facilities must inform adult patients of their right to accept or refuse treatment and to create advance directives.',TAM),
  q(HCE,'A physician writes false statements in a public letter that damage a colleague’s reputation. What is this tort?','Libel',['Slander','Fraud','Invasion of privacy'],'D','Defamation is false statements that harm a reputation. Libel is written defamation; slander is spoken.',FREM),
  q(HCE,'A clinic bills Medicare for office visits that never occurred. What has the clinic committed?','Fraud',['Malpractice','Negligence','Abandonment'],'C','Intentionally billing for services not provided is fraud. Under the False Claims Act, it can result in large fines, exclusion from Medicare and criminal charges.',FREM),
  q(HCE,'A medical assistant tells a patient that her rash is “just eczema” before the physician sees her. What is the problem?','It is outside the assistant’s scope of practice',['It violates the patient’s right to privacy','It breaches the physician’s contract','It is a form of fraud'],'A','Diagnosing is outside a medical assistant’s scope of practice. Acting beyond one’s scope can create liability for the worker and the employer.',RIT),
  q(HCE,'A therapist’s patient credibly threatens to kill a specific person. Based on the Tarasoff case, what must the therapist do?','Warn the person at risk',['Keep the threat confidential','Discharge the patient from care','Wait until the patient acts'],'B','The Tarasoff decision established a duty to warn or protect an identifiable person when a patient poses a serious threat of violence. This outweighs confidentiality.',TAM),
  q(BIO,'A hospital decides to use its limited ventilators to save the greatest number of lives. Which ethical approach does this reflect?','Utilitarian',['Deontological','Paternalism','Egoism'],'D','Utilitarianism judges actions by their outcomes, seeking the greatest good for the greatest number. Deontology focuses on duties and rules regardless of outcome.',TAM),
  q(BIO,'Which organization manages the national organ transplant waiting list and matching system in the United States?','UNOS',['The FDA','The CDC','The WHO'],'C','The United Network for Organ Sharing operates the Organ Procurement and Transplantation Network, which matches donated organs with waiting recipients.',TAM),
  q(BIO,'Under the Uniform Determination of Death Act, which finding establishes brain death?','Irreversible loss of all brain function',['Absence of a pulse for at least 2 minutes','A persistent vegetative state','Unconsciousness lasting more than 24 hours'],'A','Death can be declared after irreversible cessation of circulation and breathing, or of all functions of the entire brain, including the brainstem. A persistent vegetative state is not brain death.',TAM),
  q(BIO,'Which document names a person to make healthcare decisions if the patient cannot?','Healthcare power of attorney',['Living will','Do-not-resuscitate order','Signed medical release form'],'B','A healthcare power of attorney names a decision-maker (agent or proxy). A living will states the patient’s wishes about treatment, and a DNR is a physician’s order not to perform CPR.',FREM),
  q(BIO,'How does a do-not-resuscitate (DNR) order differ from a living will?','A DNR is a physician’s order not to perform CPR',['A DNR names a decision-maker','A DNR is written by the patient’s family','A DNR stops all medical treatment'],'D','A DNR is a medical order that CPR not be attempted if the heart stops; other care continues. A living will is the patient’s own statement of wishes.',FREM),
  q(BIO,'In states where it is legal, how does physician-assisted death differ from active euthanasia?','The patient takes the medication',['The physician gives the lethal medication','Life support is withdrawn by the family','Treatment is withheld without consent'],'C','In physician-assisted death, the physician prescribes medication that a terminally ill, competent patient self-administers. In active euthanasia, another person gives the lethal agent; it is illegal in the United States.',TAM),
  q(BIO,'What does the Genetic Information Nondiscrimination Act (GINA) prohibit?','Genetic discrimination by insurers and employers',['Genetic testing of embryos','Sharing genetic results with patients','Using DNA in criminal investigations'],'A','GINA bars health insurers and employers from using genetic information to make coverage or employment decisions. It does not cover life or long-term care insurance.',TAM),
  q(BIO,'Why is research using embryonic stem cells ethically controversial?','Obtaining the cells destroys the embryo',['The cells cannot become other cell types','The cells come only from adult donors','The cells cause cancer in every patient'],'B','Embryonic stem cells are pluripotent, which makes them valuable, but harvesting them destroys the embryo. Adult and induced stem cells avoid this concern.',TAM),
  q(BIO,'In gestational surrogacy, the surrogate:','Carries an embryo not genetically hers',['Provides her own egg for the pregnancy','Adopts the child after birth','Donates sperm for the pregnancy'],'D','In gestational surrogacy, an embryo created by IVF is transferred to the surrogate. In traditional surrogacy, the surrogate’s own egg is used, which raises more legal disputes.',TAM),
  q(BIO,'Which ethical concern is raised by preimplantation genetic diagnosis during IVF?','Selecting embryos for nonmedical traits',['Increased risk of twin births','The high cost of fertility drugs','Lack of informed consent for IVF'],'C','PGD screens embryos for genetic diseases before implantation. Critics worry about selecting embryos for traits such as sex or appearance (“designer babies”).',TAM),
  q(BIO,'The Tuskegee syphilis study led to which reform in human research?','Required informed consent and review boards',['A ban on all research with human subjects','Free treatment for all research volunteers','Research conducted only on animals'],'A','In Tuskegee, men were denied treatment and information for decades. The outcry led to the Belmont Report, informed consent requirements and institutional review boards.',TAM),
  q(BIO,'Which document, created after World War II, established that voluntary consent is essential in human research?','The Nuremberg Code',['The Hippocratic Oath','The Declaration of Independence','The Patient’s Bill of Rights'],'B','The Nuremberg Code (1947) arose from the trials of Nazi physicians and set voluntary informed consent as the first principle of ethical research.',TAM)
 ],13)
};
